def transform(grid):
    h, w = len(grid), len(grid[0])
    out_h = h // 3
    out_w = w // 3
    result = [[0] * out_w for _ in range(out_h)]
    for i in range(out_h):
        for j in range(out_w):
            colors = set()
            for r in range(3):
                for c in range(3):
                    val = grid[i * 3 + r][j * 3 + c]
                    # Filter out background colors 0 and 5 to find the 'object' color
                    if val != 0 and val != 5:
                        colors.add(val)
            if colors:
                result[i][j] = list(colors)[0]
    return result
